package org.jlinalg.sequence;

import java.io.IOException;
import java.io.StringReader;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class HomerNamedFeaturesTest {
    private static final Map<String,Long> REFERENCE=Map.of("chr1",1000L,"chr2",1000L,"chr3",1000L);
    private static HomerNamedFeatures.Query q(String id,int start,int end,char strand){return new HomerNamedFeatures.Query(id,"chr1",start,end,strand);}
    private static HomerNamedFeatures.Limits limits(boolean retain){return new HomerNamedFeatures.Limits(10000,100,1000,100,10000,100000,retain);}
    private static HomerNamedFeatures.Summary run(String text,List<HomerNamedFeatures.Query> queries,boolean retain)throws Exception{return HomerNamedFeatures.annotate(new StringReader(text),REFERENCE,queries,limits(retain),()->{});}
    @Test void integerMidpointsAndInclusiveBoundariesMatchOriginalSourceProbe()throws Exception{var s=run("left-repeat--123\tchr1\t0\t100\t+\tR\t1\nright-gene-HOMER3\tchr1\t101\t300\t-\tE\t2\n",List.of(q("left",100,101,'+'),q("right",101,102,'-'),q("wide",1,205,'+')),false);assertEquals(List.of("left-repeat","right-gene","right-gene"),s.matches().stream().map(m->m.compatible().get(0).originalDisplayName()).toList());assertEquals(Map.of("R",101L,"E",200L),s.queryContigBackgroundBases());}
    @Test void backgroundIncludesOnlyInputContigsAndMissingAssignmentsStayExplicit()throws Exception{var missing=new HomerNamedFeatures.Query("missing","chr3",10,20,'+');var s=run("a\tchr1\t1\t100\t+\tE\t1\nb\tchr2\t1\t1000\t+\tR\t2\n",List.of(q("known",50,50,'+'),missing),false);assertEquals(Map.of("E",100L),s.queryContigBackgroundBases());assertEquals(1,s.unassignedQueries());assertTrue(s.matches().get(1).compatible().isEmpty());}
    @Test void constructionPriorityDoesNotReplaceOriginalGeometrySort()throws Exception{var s=run("later-priority\tchr1\t50\t80\t+\tP\t0\nearlier-geometry\tchr1\t1\t100\t-\tR\t1900000000\n",List.of(q("query",75,75,'+')),false);assertEquals("earlier-geometry",s.matches().get(0).compatible().get(0).name());assertEquals(1900000000,s.matches().get(0).compatible().get(0).constructionPriority());}
    @Test void equalGeometryKeepsAllCompatibleNamesAndCategories()throws Exception{var s=run("isoformA\tchr1\t10\t20\t+\tE\t4\nisoformB\tchr1\t10\t20\t+\tR\t3\n",List.of(q("query",15,15,'-')),false);assertEquals(1,s.geometryTiedQueries());assertEquals(2,s.matches().get(0).compatible().size());assertTrue(s.matches().get(0).acceptsDisplayName("isoformA"));assertTrue(s.matches().get(0).acceptsDisplayName("isoformB"));assertEquals(Map.of("E",11L,"R",11L),s.queryContigBackgroundBases());}
    @Test void endThenStrandBreakGeometryTiesWithoutUsingInputQueryStrand()throws Exception{var s=run("long\tchr1\t10\t40\t+\tR\t0\nminus\tchr1\t10\t30\t-\tR\t0\nplus\tchr1\t10\t30\t+\tE\t99\n",List.of(q("query",20,20,'-')),false);assertEquals(List.of("plus"),s.matches().get(0).compatible().stream().map(HomerNamedFeatures.Feature::name).toList());}
    @Test void resourceBoundsRequirePermissionAndPreserveSourceSizeRules()throws Exception{String data="negative\tchr1\t-5\t5\t+\tN\t0\noverhang\tchr1\t900\t1100\t+\tE\t1\n";assertThrows(IOException.class,()->run(data,List.of(q("query",950,950,'+')),false));var s=run(data,List.of(q("query",950,950,'+')),true);assertEquals(1,s.negativeStartRecords());assertEquals(1,s.endBeyondReferenceRecords());assertEquals(Map.of("E",201L),s.queryContigBackgroundBases());assertEquals(1100,s.matches().get(0).compatible().get(0).end1());}
    @Test void unknownResourceContigsRemainCountedUnderExplicitRetention()throws Exception{var s=run("known\tchr1\t1\t20\t+\tE\t1\nunknown\tchrX\t1\t100\t+\tR\t2\n",List.of(q("query",10,10,'+')),true);assertEquals(1,s.missingReferenceRecords());assertEquals(Map.of("E",20L),s.queryContigBackgroundBases());}
    @Test void sourceNamesAndDisplayCleanupRemainSeparate()throws Exception{var s=run("repeat--123\tchr1\t1\t10\t+\tLINE\t1\n",List.of(q("query",2,2,'+')),false);var f=s.matches().get(0).compatible().get(0);assertEquals("repeat--123",f.name());assertEquals("repeat",f.originalDisplayName());assertFalse(s.matches().get(0).acceptsDisplayName("other"));assertThrows(UnsupportedOperationException.class,()->s.matches().get(0).compatible().clear());}
    @Test void malformedResourcesAndOversizedLinesFailExplicitly(){for(String text:List.of("", "bad\tchr1\t20\t10\t+\tE\t0\n","bad\tchr1\t1\t10\t.\tE\t0\n","bad\tchr1\t1\t10\t+\tE\t0\textra\n","bad\tchr1\t1\t10\t+\tE\t-1\n","bad\rname\tchr1\t1\t10\t+\tE\t0\n"))assertThrows(Exception.class,()->run(text,List.of(q("query",2,2,'+')),false));var small=new HomerNamedFeatures.Limits(10,10,10,10,32,100,false);assertThrows(IOException.class,()->HomerNamedFeatures.annotate(new StringReader("a".repeat(50)+"\tchr1\t1\t10\t+\tE\t0\n"),REFERENCE,List.of(q("query",2,2,'+')),small,()->{}));}
    @Test void queryIdentityReferenceAndSafeIntegerBoundsAreChecked(){assertThrows(IllegalArgumentException.class,()->q("q",0,10,'+'));assertThrows(IllegalArgumentException.class,()->q("q",1,1_000_000_001,'+'));assertThrows(IOException.class,()->run("a\tchr1\t1\t10\t+\tE\t0\n",List.of(q("same",2,2,'+'),q("same",3,3,'+')),false));assertThrows(IOException.class,()->run("a\tchr1\t1\t10\t+\tE\t0\n",List.of(q("q",1001,1001,'+')),false));}
    @Test void candidateCategoryAndOperationCapacitiesRejectWholeIncompleteAudits(){String data="a\tchr1\t1\t10\t+\tE\t0\nb\tchr1\t1\t10\t+\tR\t0\n";for(var l:List.of(new HomerNamedFeatures.Limits(10,10,1,10,1000,100,false),new HomerNamedFeatures.Limits(10,10,10,1,1000,100,false),new HomerNamedFeatures.Limits(10,10,10,10,1000,1,false),new HomerNamedFeatures.Limits(1,10,10,10,1000,100,false)))assertThrows(IOException.class,()->HomerNamedFeatures.annotate(new StringReader(data),REFERENCE,List.of(q("q",2,2,'+')),l,()->{}));}
    @Test void callerDeadlineFailurePropagatesBeforeReading(){assertThrows(IOException.class,()->HomerNamedFeatures.annotate(new StringReader("a\tchr1\t1\t10\t+\tE\t0\n"),REFERENCE,List.of(q("q",2,2,'+')),limits(false),()->{throw new IOException("deadline");}));}
    @Test void crlfFinalLineAndInputOrderAreRetained()throws Exception{var s=run("#comment\r\na\tchr1\t1\t10\t+\tE\t0\r\nb\tchr1\t20\t30\t+\tR\t0",List.of(q("later",25,25,'-'),q("earlier",5,5,'+')),false);assertEquals(List.of("later","earlier"),s.matches().stream().map(m->m.query().id()).toList());assertEquals(2,s.resourceRecords());}
    @Test void originalSentinelIntervalsStayUnclippedAndOutOfSizeTotals()throws Exception{var s=run("real\tchr1\t1\t100\t+\tE\t0\nsentinel\tchr1\t101\t1500000000\t+\tN\t1900000000\n",List.of(q("near",50,50,'+'),q("far",500,500,'+')),true);assertEquals(1500000000,s.matches().get(1).compatible().get(0).end1());assertEquals(Map.of("E",100L),s.queryContigBackgroundBases());assertEquals(1,s.endBeyondReferenceRecords());assertThrows(IOException.class,()->run("unsafe\tchr1\t1000000000\t1500000000\t+\tN\t0\n",List.of(q("q",10,10,'+')),true));}
}
